function seasonBackLink(){return '<div class="breadcrumb"><a class="season-back-link" href="#seasons"><span aria-hidden="true">←</span>火热赛季</a></div>';}
'use strict';
/* 面包屑里显示赛季名而不是编号（S01/W01 这类代号只用于内部路由）。 */
const publicCrumb=(title)=>`<div class="breadcrumb"><a href="#seasons">火热赛季</a><span>/</span><a href="#season?code=${esc(state.season.code)}">${esc(state.season.name.replace(/^BoomLand\s*/,''))}</a><span>/</span><span>${esc(title)}</span></div>`;
const projectTags=p=>guestProjectChallengeTags(p);
function challengeCard(c){return guestChallengeCard(c,{showTarget:true});}
/* 资源兑现状态（CHG-004）：c1 与企业端维护的 state.resources 联动；其余命题按资源项展示演示状态。 */
function challengeResourceChips(c){
 if(c.id==='c1'&&Array.isArray(state.resources))return [['测试算力',state.resources[0]],['专家支持',state.resources[1]],['园区试点',state.resources[2]]];
 const statuses=['已提供','可申请','已承诺'];
 return String(c.resource||'').split(/[、,，]/).map(s=>s.trim()).filter(Boolean).slice(0,3).map((name,i)=>[name,statuses[i%statuses.length]]);
}
/* 长期项目库（9.7）不显示赛季贡献积分：积分按赛季建账，仅在赛季语境（命题页等）展示。 */
function projectCard(p,{score=true}={}){return `<article class="project-card"><div class="project-icon">${esc(p.icon||'✳')}</div><div class="row between"><h3>${esc(p.name)}</h3>${badge(p.stage,p.growth==='认证'?'green':'')}</div><p class="muted small">${esc(p.tagline||p.description||'一个正在生长的新项目。')}</p><div class="chips">${projectTags(p)}</div><div class="row between" style="margin-top:22px">${score?`<span><strong class="score">${projectScore(p)}</strong><span class="small muted">赛季贡献积分</span></span>`:'<span></span>'}<a class="link" href="#project?id=${p.id}">进入项目 ↗</a></div></article>`;}
function rankingTable(){const projects=[...allProjects()].sort((a,b)=>projectScore(b)-projectScore(a));return listState(table(['排名','项目','命题','项目积分','奖励状态'],projects.filter(p=>activeFilter==='全部'||p.challenges.includes(activeFilter)).map((p,i)=>[`<span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>`,`<a href="#project?id=${p.id}"><strong>${esc(p.name)}</strong><span class="sub">${esc(p.members.join('、'))}</span></a>`,projectTags(p),`<strong>${projectScore(p)}</strong>`,`<strong>${state.phase==='cancelled'?'不发奖':money(projectScore(p)*state.season.ratio)}</strong><span class="sub">${state.phase==='cancelled'?'赛季已取消':state.rewardsPaid?'已发放':['ended','archived'].includes(state.phase)?'已核定':'预计，未结算'}</span>`])));}
function workList(works=state.works,scoreMode=false){works=works.filter(canViewWork);return listState(works.length?`<div class="result-list">${works.map(w=>`<div><div class="row between"><div class="chips">${badge(w.type)}${badge('V'+w.version)}${badge(workScore(w)?'已评分':'待评分',workScore(w)?'green':'')}</div><span class="small muted">${esc(w.date)}</span></div><h3 style="margin-top:12px"><a href="#${scoreMode?'score':'work'}?id=${w.id}">${esc(w.title)}</a></h3><p class="small muted">${esc(projectBy(w.projectId).name)} · ${esc(w.author)}</p><div class="row between"><span class="small">作品合计 <strong>${workScore(w)}</strong> 分</span>${button(scoreMode?'查看与评分':'查看作品',`#${scoreMode?'score':'work'}?id=${w.id}`,'sm')}</div></div>`).join('')}</div>`:empty('还没有作品','开始记录你的行动，作品发布本身不会自动产生积分。',state.role==='participant'?button('发布第一件作品','#new-work','primary'):''));}
function seasonRewardRuleItems(){return [
 ['单次评分上限',state.season.cap+' 积分'],
 ['积分兑换','1 积分 = '+state.season.ratio+' 元；开赛后比例不变，预计不等于已发放'],
 ['大额复核',state.season.threshold+' 分起需第二人复核'],
 ['奖励预算',state.season.budget==null?'待公布':money(state.season.budget)],
 ['积分池总量',state.season.pool??'待公布'],
 ['积分归属','积分归项目，不按命题分账；发布作品或通过里程碑不自动产生积分'],
 ['奖励核定',state.phase==='cancelled'?'积分保留为档案，不发奖。':'结算前为预计金额，不代表已核定或已发放；以核定和发放记录为准。']
];}
function rules({hideScoring=false}={}){
 const items=[['核心团队','1—'+(state.season.teamLimit||3)+' 人，允许单人项目'],['项目命题','1—'+(state.season.challengeLimit||3)+' 个，完全平行，没有主次'],['每人项目数','本季 '+(state.season.projectLimit||1)+' 个'],['评分方式','作品滚动评分，多位评委分别赋分并叠加'],...seasonRewardRuleItems(),['作品截止',state.season.dates[5]+'，北京时间'],['评分截止',state.season.dates[6]+'，北京时间']];
 if(hideScoring){const remove=new Set(['评分方式','单次评分上限','积分兑换','大额复核','奖励预算','积分池总量','积分归属','奖励核定','评分截止']);for(let i=items.length-1;i>=0;i--)if(remove.has(items[i][0]))items.splice(i,1);items.push(['活动形式','本活动不计分，不计算积分或预计奖金']);}
 const requiredCount=items.length;items.push(...(state.season.optionalRules||[]).map((rule,i)=>['补充规则 '+(i+1),rule]));
 return `<div data-rule-card><ul class="rule-list" id="season-full-rules">${items.map(([label,value],i)=>`<li ${i>=requiredCount?'data-extra-rule hidden':''}><strong>${esc(label)}</strong><span>${esc(value)}</span></li>`).join('')}</ul>${items.length>requiredCount?'<button type="button" class="link rules-toggle" data-action="toggle-rules" aria-expanded="false" aria-controls="season-full-rules">展开全部规则</button>':''}</div>`;
}

function timeline(){return seasonDetailTimeline();}

function activityOrder(item){return {'即将开始':0,'报名中':1,'进行中':2,'已结束':3}[item.group]??3;}
/* 待定 17：类型只有常规赛季与黑客松；预热季、共学季、工作坊等用「形式标签」区分展示。
   标签只认 SEASON_FORMAT_LABELS 白名单，黑客松忽略形式标签；白名单外的值按常规赛季处理。 */
function seasonFormatTag(record=state){return record.season.type!=='hackathon'&&SEASON_FORMAT_LABELS.includes(record.season.formatLabel)?record.season.formatLabel:'';}
function seasonFormatLabel(record=state){return record.season.type==='hackathon'?'黑客松':(seasonFormatTag(record)||'常规赛季');}
function featuredEvents(){return ['S01','W01','H02'].map(publicActivityInfo).filter(e=>e.record.season.approved&&!e.record.season.draft);}

function selectedFeaturedEvent(events=featuredEvents()){const requested=new URLSearchParams(location.hash.split('?')[1]||'').get('code');return events.find(e=>e.code===requested)||events.find(e=>e.code===state.pinnedSeasonCode)||events.find(e=>e.code===state.bannerCode)||events.filter(e=>e.record.phase==='active').sort((a,b)=>b.record.applications.filter(p=>p.status==='已通过').length-a.record.applications.filter(p=>p.status==='已通过').length)[0]||events[0];}
function selectFeaturedEvent(code){if(!featuredEvents().some(e=>e.code===code))return;state.bannerCode=code;save();go('seasons?code='+encodeURIComponent(code));render();}

/* 火热赛季网格只含进行中、即将开始与报名中的活动（9.6、ARC-001）；已结束的活动只出现在往季档案。 */
function homeEventTickets(){return featuredEvents().map(e=>{const metrics=withPublicActivity(e.code,guestEventMetrics);const capacity=e.record.season.participantCapacity;const registration=registrationDisplayLabel(e.record);return {code:e.code,title:e.name,description:e.description,status:e.status,seasonStatus:e.status,registrationStatus:registration,group:e.group,date:e.date,frame:e.code==='S01'?'49408.svg':'a8e9c.svg',dot:['报名中','进行中'].includes(e.group)?'e3a11.svg':'7ed0d.svg',tone:['报名中','进行中'].includes(e.group)?'pink':'yellow',roller:e.code==='S01',canRegister:e.record.registration==='open'&&['upcoming','active','workClosed'].includes(e.record.phase),showParticipation:e.record.phase!=='upcoming'||e.record.registration==='open',url:e.url,live:e.group==='进行中',scoringEnabled:e.record.season.scoringEnabled!==false&&e.record.season.scoring!==false&&!e.record.season.noScoring,organizer:seasonOrganizerLabel(e.record),type:seasonFormatLabel(e.record),metrics,detailsPublished:e.record.publicSummary?.detailsPublished!==false,capacity:capacity||null,count:metrics.approved,projects:metrics.projects,bar:capacity?Math.min(240,metrics.approved/capacity*240):0};}).filter(c=>c.group!=='已结束').sort((a,b)=>activityOrder(a)-activityOrder(b));}

function eventTicketGrid(){const a='assets/season-cards/';const cards=homeEventTickets().filter(c=>activeFilter==='全部'||c.group===activeFilter);return `<div class="event-ticket-grid" data-node-id="253:2429">${cards.map(c=>`<div class="event-ticket"><div class="event-ticket-canvas"><a class="event-ticket-link" href="${c.url}" aria-label="查看${esc(c.title)}详情"><img class="event-ticket-base" src="${a}254f9.svg" alt=""><div class="event-ticket-clip"><span class="event-ticket-cover"><img class="event-ticket-photo" src="${a}7467c.png" alt="">${c.roller?`<img class="event-ticket-roller" src="${a}85dbf.png" alt="">`:''}<span class="event-ticket-code">${c.code}</span><span class="event-ticket-statuses"><span class="event-ticket-status ${c.tone}"><img src="${a+c.dot}" alt="">${esc(c.seasonStatus)}</span>${c.registrationStatus?`<span class="event-ticket-status reg">${esc(c.registrationStatus)}</span>`:''}</span></span><div class="event-ticket-content"><div class="event-ticket-heading"><h3>${esc(c.title)}</h3><span class="event-ticket-organizer">${esc(c.organizer)}</span></div><p>${esc(c.description)}</p><div class="event-ticket-metrics">${esc(c.type)}${c.detailsPublished?' · '+c.metrics.challengeCount+' 个命题':''}${c.scoringEnabled?(c.metrics.budget!=null?' · 奖励池 '+guestMoney(c.metrics.budget):''):' · 不计分活动'}</div><div class="event-ticket-date"><span class="event-ticket-calendar"><img src="${a}672ef.svg" alt=""></span><span>${c.date}</span></div>${c.live?`<div class="event-ticket-projects${c.canRegister?' narrow':''}"><span><img src="${a}03311.svg" alt=""></span><span class="event-ticket-stats-text">${c.detailsPublished?c.metrics.approved+' 选手 · ':''}${c.projects} 项目 · ${c.metrics.works} 作品 · R5 项目 ${c.metrics.r5}${c.scoringEnabled?' · 积分池 '+c.metrics.allocationRate:''}</span></div>`:c.showParticipation&&(c.capacity||c.canRegister)?`<div class="event-ticket-quota"><div><span>已通过 ${c.count}/${c.capacity||'不限'}</span>${c.capacity?`<span>剩余 ${Math.max(0,c.capacity-c.count)} 个名额</span>`:''}</div>${c.capacity?`<div class="event-ticket-track"><span style="width:${c.bar}px"></span></div>`:''}</div>`:''}</div></div></a>${c.canRegister?`<button type="button" class="event-ticket-button" data-action="register-public-activity:${c.code}"><span>立即报名</span><img src="${a}370e4.svg" alt=""></button>`:''}<img class="event-ticket-frame" src="${a+c.frame}" alt=""></div></div>`).join('')}</div>`;}
function seasonsPage(){const events=featuredEvents(),featured=selectedFeaturedEvent(events);return layout(`<section class="hero guest-hero" aria-label="本季推荐"><div class="hero-body">${`<div class="hero-activity-meta">${badge(featured.status,'pink')}${registrationDisplayLabel(featured.record)?badge(registrationDisplayLabel(featured.record)):''}${badge(seasonFormatLabel(featured.record))}<span>${esc(seasonOrganizerLabel(featured.record))}</span></div>`}<h1>BoomLand<span>${esc(featured.name)}</span></h1><p class="tagline">${esc(featured.description)}</p><div class="hero-meta"><img src="assets/calendar.svg" alt=""><span>活动 ${esc(featured.date)}</span></div><div class="hero-meta"><img src="assets/users.svg" alt=""><span>${esc(featured.count)}</span></div></div><a href="${featured.url}" class="hero-cta"><img class="ticket" src="assets/ticket.svg" alt=""><span>探索本季</span><img class="arrow" src="assets/arrow.svg" alt=""></a><div class="hero-bottom"><button class="hero-arrow" data-action="season-prev" aria-label="上一个赛季"><img src="assets/previous.svg" alt=""></button>${events.map(e=>`<button type="button" class="hero-switch ${e.code===featured.code?'active':''}" data-action="featured-event:${e.code}" aria-pressed="${e.code===featured.code}">${esc(e.name)}<small>${esc(e.status)}</small></button>`).join('')}<button class="hero-arrow" data-action="season-next" aria-label="下一个赛季"><img src="assets/next.svg" alt=""></button></div></section><div class="container wide"><div class="filter-bar">${tabs(['全部','即将开始','报名中','进行中'],activeFilter)}${`<div class="row"><a class="link archive-highlight" href="#archive">往季档案 · ${guestArchiveRecords().length}</a><a class="link" href="#challenges">命题库 ↗</a></div>`}</div>${listState(eventTicketGrid())}</div>`);}
/* 赛季详情页只有一套实现（guestSeasonPage）；草稿与待批准赛季对管理者走同一页面，
   顶部由 seasonPreviewBanner 显示「待平台批准·未公开」与批准/驳回（SDP-001、9.9）。 */
function seasonPage(){
 const code=new URLSearchParams(location.hash.split('?')[1]||'').get('code')||state.season.code;
 return guestSeasonPage(code);
}
function challengePage(){const c=currentChallenge();if(!canReadChallenge(c))return layout(`<div class="container">${empty('命题不存在', '',button('返回命题库','#challenges'))}</div>`);return layout(`<div class="container">${publicCrumb('企业命题')}<nav class="tabs"><a class="active" href="#challenge?id=${encodeURIComponent(c.id)}">内容</a><a href="#challenge-progress?id=${encodeURIComponent(c.id)}">项目进度</a></nav>${pageHead(c.name,c.description,c.status==='已发布'&&c.taken<c.capacity?button('选择这个命题','#create-project','primary'):badge(c.status==='已发布'?'已满额':c.status))}<div class="chips" style="margin-bottom:24px">${badge(c.company,'pink')}${badge(c.type)}${badge(c.taken===c.capacity?'名额已满':'已发布',c.taken===c.capacity?'yellow':'green')}</div><div class="grid cols-2">${panel('我们想解决的问题','让企业需求变成可验证的项目目标。',`<p class="description">${esc(c.description)}</p><ul class="rule-list"><li><strong>目标用户</strong><span>${esc(c.audience||'正在验证新方案的中小团队与产业合作方')}</span></li><li><strong>最小成果</strong><span>${esc(c.target)}</span></li><li><strong>项目容量</strong><span>已选 ${c.taken} / ${c.capacity} 个项目</span></li></ul>`)}${panel('企业提供的支持','资源按承诺和兑现状态分别记录。',`<p>${esc(c.resource)}</p><div class="chips">${challengeResourceChips(c).map(([name,status])=>badge(name+' · '+status,status==='已提供'?'green':status==='可申请'?'yellow':'')).join('')}</div>`)}</div><div class="grid cols-2" style="margin-top:24px">${panel('完成标准与证据','不要求所有类型的命题都在短期内形成收入。',`<p>${esc(c.target)}</p><p>${esc(c.evidence)}</p><p class="muted">保留访谈、原型、客户反馈或验收记录，由授权核验员确认商业结果。</p>`)}${panel('公开与权益说明','接受命题时确认当前条款版本。',`<p>${esc(c.rights||'项目保留知识产权。企业可在授权范围内查看本命题材料，后续采购、投资或许可另行签约。')}</p>${c.exclusive?notice('这个命题包含独家使用条件，选择前请单独确认。'):''}${button('查看评分参考','#score-guide','sm')}`)}</div>${sectionHead('已经开始行动的团队')}<div class="grid cols-3">${allProjects().filter(p=>p.challenges.includes(c.id)).map(projectCard).join('')}</div></div>`);}
function challengesPage(){return guestChallengeLibrary();}
function archivePage(){return guestArchivePage();}
function rankingsPage(){if(['ended','archived'].includes(state.phase))return guestFinalResultsPage();return layout(`<div class="container">${publicCrumb('排行榜')}${pageHead('让每一次真实贡献，都有迹可循。','按项目赛季贡献积分排名。预计奖金未结算，收入不参与积分合并。')}${phaseNotice()}<div class="filter-bar"><div class="row"><button class="btn sm ${activeFilter==='全部'?'primary':''}" data-action="filter" data-value="全部">全部命题</button>${selectableChallenges().map(c=>`<button class="btn sm ${activeFilter===c.id?'primary':''}" data-action="filter" data-value="${c.id}">${c.company}</button>`).join('')}</div>${badge('数据来自有效评分','green')}</div>${['upcoming'].includes(state.phase)?empty('赛季尚未开始','开赛后将展示项目积分与实时排名。'):rankingTable()}${sectionHead('商业成果')}${rankingsResultsSection()}</div>`);}
/* 商业成果与赛季详情页战果同一口径（SDP-001）：复用 guestOutcomes，只展示已核验的 R3–R6，不收 R2 与自述成果。 */
function rankingsResultsSection(){
 const labels={R3:'完成外部试用或真实交付',R4:'形成明确商业承诺',R5:'形成实际收入',R6:'形成持续合作'};
 const items=['upcoming'].includes(state.phase)?[]:guestOutcomes();
 return items.length?`<div class="grid cols-3">${items.map(o=>panel(o.project.name,'已核验成果',`${badge(o.level,'green')}<p style="margin-top:12px">${labels[o.level]}</p><p class="small muted">具体收入：未公开</p>`)).join('')}</div>`:empty('暂无公开成果','项目提交商业结果并通过核验后，会在这里展示已核验的 R3–R6 等级。');
}
function applyPage(){if(state.role==='visitor')return guestApplyGate();if(new URLSearchParams(location.hash.split('?')[1]||'').get('code')==='H02')return layout(`<div class="container">${empty('报名已截止','',button('查看活动详情','#season?code=H02'))}</div>`);const upcoming=upcomingEventFromRoute();if(upcoming)return layout(`<div class="container">${empty('报名未开放','',button('查看活动详情','#season?code='+upcoming.code,'primary'))}</div>`);const blocked=canWrite('apply');if(state.application&&state.application.status!=='已撤回')return layout(`<div class="container">${publicCrumb('赛季报名')}${pageHead('你已经提交过本季报名','无需重复报名，可以在我的赛季查看审核进度。')}${button('查看报名进度','#workspace','primary')}</div>`);return layout(`<div class="container" style="max-width:900px">${publicCrumb('个人报名')}${pageHead('先加入，再一起找到方向。','个人报名不要求已有项目、队伍或正式命题。通过审核后，主办方会邀请你加入微信群。')}${blocked?notice(esc(blocked)):''}${panel('个人报名表','',form('apply',`<div class="form-section"><h2>认识一下你</h2><div class="form-grid">${field('你的名字','name','text','叶青')}${field('微信联系方式','wechat','text','',false,'','只供主办方拉群使用，不会公开展示。')}${field('技能与经历','skills','text','',true)}${selectField('每周可投入时间','time',['5—8 小时','8—12 小时','12 小时以上'],'8—12 小时')}${selectField('感兴趣的产业方向','direction',['园区算力','创作者合作','产业研究','暂未确定'])}</div></div><div class="form-section"><h2>你想怎样参与</h2><div class="form-grid">${textarea('合作和组队意向','team','我愿意先从单人开始，也希望认识互补的队友。')}${check('我已阅读参赛规则，确认所填信息真实，并同意仅将微信用于本季拉群。')}</div></div>`,'提交个人报名',!!blocked))}</div>`);}
function createProjectPage(){const blocked=canWrite('project');return layout(`${pageHead('把一个问题，变成你的项目。','正式命题归属在项目创建时确定，不在个人报名时确定。')}${blocked?notice(esc(blocked)):''}${state.ownProject?notice('你已经有一个本季项目，每人默认参与一个项目。请进入已有项目。','pink')+button('进入我的项目','#project','primary'):panel('项目登记','带入长期项目时，只能选择本人发起的项目。',form('create-project',`<div class="form-grid">${selectField('参赛方式','source',[['new','新建一个项目'],['existing','带入本人已有项目']],'new',true)}${field('项目名称','name')}${field('核心成员姓名','members','text','叶青')}${textarea('一句话介绍与初始方案','description','','说明你想解决什么问题，以及准备怎样验证。')}<div class="field full"><label class="required">选择一到三个平行命题</label><div class="grid">${selectableChallenges().map(c=>`<label class="choice ${c.taken>=c.capacity?'disabled':''}"><input type="checkbox" name="challenges" value="${c.id}" ${c.taken>=c.capacity?'disabled':''}><span><strong>${esc(c.name)}</strong>${esc(c.company)}，已选 ${c.taken}/${c.capacity}。${c.exclusive?'包含独家条件。':''}</span></label>`).join('')}</div></div>${selectField('项目公开范围','visibility',[['public','项目介绍公开'],['members','仅团队与审核人员']],'public',true)}${check('我确认核心成员已通过本季报名，且逐项阅读并同意所选命题的权益条款。')}</div>`,'登记并进入项目',!!blocked))}`,'participant');}
function selectedProject(){const id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');return id?projectBy(id):state.ownProject||PROJECTS[0];}
function projectPage(){const p=selectedProject(),own=p.id===state.ownProject?.id,milestones=state.milestones.filter(m=>m.projectId===p.id),results=state.results.filter(item=>item.projectId===p.id&&(item.visibility==='public'||isManager()||own));return layout(`<div class="container">${publicCrumb('项目详情')}${pageHead(p.name,p.tagline||p.description,own?(state.phase==='active'?button('发布赛季作品','#new-work','primary')+button('提交里程碑','#milestone'):button('查看我的赛季','#workspace','primary')):button('查看所有项目','#projects'))}<div class="chips" style="margin-bottom:25px">${badge(p.stage,'green')}${badge(p.growth||'自述')}${projectTags(p)}${badge(state.season.code)}</div><div class="grid cols-4">${stat('本季贡献积分',projectScore(p),'仅统计本季有效评分')}${stat('预计奖金',money(projectScore(p)*state.season.ratio),'预计，未结算')}${stat('赛季作品',state.works.filter(w=>w.projectId===p.id).length,'持续留下过程证据')}${stat('商业成果',p.r||'R0','收入金额默认不公开')}</div>${sectionHead('项目介绍与团队','','01')}${panel('我们正在做什么',p.members.join('、'),`<p class="description">${esc(p.description||p.tagline)}</p><div class="row">${badge('知识产权归项目方')}${badge('命题平行，不分主次')}</div>`)}${sectionHead('阶段进展','','02')}<div class="milestones">${['验证真实问题','形成可交付方案','外部试用或交付','达成命题关键结果'].map((t,i)=>`<${own?'a href="#milestone?step='+(i+1)+'"':'div'} class="milestone ${(milestones.filter(m=>m.status==='已通过').length===i)?'active':''}"><strong>M${i+1}</strong><h3>${t}</h3><span class="small muted">${milestones.find(m=>m.step===i+1)?.status||'查看要求与证据'}</span></${own?'a':'div'}>`).join('')}</div>${sectionHead('作品与真实行动',own&&state.phase==='active'?button('发布作品','#new-work','sm'):'','03')}${workList(state.works.filter(w=>w.projectId===p.id))}${sectionHead('商业结果与后续合作',own&&state.phase==='active'?button('提交商业结果','#result','sm'):'','04')}${panel('用证据确认成果','核验不自动产生积分或独立结果奖励。',results.length?results.map(r=>`<div class="feed-item"><div><strong>${esc(r.title)}</strong><p>${badge(r.status)} ${esc(r.level)}</p></div></div>`).join(''):empty('还没有新的核验记录','真实交付、订单或收入都可以作为成果的证明。'))}</div>`);}
function newWorkPage(){const blocked=canWrite('work');return layout(`${pageHead('记录这一次真实行动','作品会关联当前项目和赛季。请把过程、证据与新增思考讲清楚。')}${blocked?notice(esc(blocked)):''}${notice(`发布到：<strong>${esc(state.ownProject?.name||'尚未创建项目')}</strong> / ${esc(state.season.name.replace(/^BoomLand\s*/,''))}`,'pink')}${panel('赛季作品','微信群内容不会自动成为平台作品，需要主动整理后发布。',form('work',`<div class="form-grid">${field('作品标题','title','text','',true)}${selectField('作品类型','type',['想法','研究','访谈','过程记录','原型','客户反馈','交付','复盘'])}${selectField('命题标注（可选）','tag',[['','不标注'],...(state.ownProject?.challenges||[]).map(id=>[id,organizerChallenges().find(c=>c.id===id)?.company||'企业命题'])])}${textarea('作品正文','body','','说明做了什么、看到了什么证据，以及下一步要验证什么。')}${field('摘要','summary','text','',true,'minlength="8"')}${selectField('公开范围','visibility',[['public','公开'],['members','仅共建成员'],['verification','仅核验人员']])}<div class="field"><label for="evidence">附件（本机仅记录文件名）</label><input type="file" name="evidence" id="evidence" multiple><span class="help">此原型不上传文件内容。</span></div>${check('申请评委评分；我确认这是本项目的真实进展。','review',false)}</div>`,'发布赛季作品',!!blocked))}`,'participant');}
function workPage(){const w=currentWork();if(!w)return layout('<div class="container">'+empty('还没有赛季作品','请先发布一件作品。')+'</div>');const p=projectBy(w.projectId),records=state.ledger.filter(l=>l.workId===w.id&&l.version===w.version);return layout(`<div class="container" style="max-width:1050px">${publicCrumb('作品详情')}${pageHead(w.title,`${p.name} / ${w.author} / ${w.date}`,state.role==='judge'?button('对这件作品评分',`#score?id=${w.id}`,'primary'):'')}<div class="chips" style="margin-bottom:22px">${badge(w.type)}${badge('版本 '+w.version)}${badge(w.visibility==='public'?'公开':'仅授权可见')}${badge(workScore(w)?'已评分':'待评分',workScore(w)?'green':'')}</div>${!canViewWork(w)?notice('这件作品的材料仅对共建或核验权限开放。'):panel('作品内容','当前版本的过程、证据与下一步。',`<div class="work-body">${w.body.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="evidence"><span>▧</span><span>${esc(w.evidence.join('、')||'暂未添加附件')}</span><span class="badge">附件记录</span></div>`)}${sectionHead('评分明细',`<strong>作品合计 ${workScore(w)} 分</strong>`)}${table(['评委','分数','理由','状态'],records.map(l=>[esc(l.judge),l.reversed?`<s>${l.points}</s>`:'+'+l.points,esc(l.reason),badge(l.reversed?'已冲正':l.reviewed?'已评分':'待复核',l.reversed?'':l.reviewed?'green':'yellow')]))}${sectionHead('历史版本')}${panel('V'+w.version,w.date,`<p>${esc(w.increment)}</p><p class="small muted">旧内容和评分会保留。新增版本只有真实增量才可以再申请评分。</p>`)}</div>`);}
function milestonePage(){const step=Math.max(1,Math.min(4,Number(new URLSearchParams(location.hash.split('?')[1]||'').get('step'))||state.milestones.filter(m=>m.status==='已通过').length+1)),names=['验证真实问题','形成可交付方案','完成外部试用或交付','达成命题关键结果'],record=state.milestones.find(m=>m.step===step);return layout(`<div class="container" style="max-width:950px">${publicCrumb('里程碑')}${pageHead('M'+step+' / '+names[step-1],'里程碑用于阶段认证，通过本身不自动增加项目积分。')}<div class="grid cols-2">${panel('本阶段要完成什么','证据门槛以所选企业命题的版本为准。',`<p>${['证明问题真实存在，说明客户是谁，以及你看到了哪些需求证据。','提供外部可以理解和评价的方案、服务、原型或研究成果。','提交外部试用、真实交付或等效证据，达到命题要求。','达到所选命题预设的关键结果，商单验证型以真实收入为目标。'][step-1]}</p>`)}${panel('最低证据','可以关联已经发布的赛季作品，不重复要求重新写作。',`<ul><li>${['客户访谈与需求记录','方案、原型或服务说明','试用记录与客户反馈','命题要求的交付、合作或收入证明'][step-1]}</li><li>说明证据如何满足本阶段要求</li><li>主办方或平台管理员审核</li></ul>`)}</div><div style="margin-top:24px">${record?notice('当前状态：'+esc(record.status),'green'):''}${state.role==='participant'?panel('提交阶段认证','必须按 M1 到 M4 顺序进行，不能跳级或重复通过。',form('milestone',`<input type="hidden" name="step" value="${step}"><div class="form-grid">${selectField('关联赛季作品','workId',state.works.filter(w=>w.projectId===state.ownProject?.id).map(w=>[w.id,w.title]),'',true)}${step>=3?selectField('依据的项目命题','challenge',(state.ownProject?.challenges||[]).map(id=>[id,organizerChallenges().find(c=>c.id===id)?.name||'命题']),'',true):''}${textarea('提交说明','description','','不少于十二字，解释证据如何满足完成条件。')}</div>`,'提交审核',!!canWrite('milestone')||!!record)):notice('项目成员可以从这里提交认证；访客仅查看完成条件。')}</div></div>`);}
function resultPage(){const blocked=canWrite('result');return layout(`${pageHead('让成果经得起验证','提交真实交付、订单、收入或持续合作证据。')}${blocked?notice(esc(blocked)):''}${panel('商业结果申报','私密证明不因成果等级公开而自动公开。',form('result',`<div class="form-grid">${field('成果标题','title','text','',true)}${selectField('申报等级','level',[['R3','R3 外部试用或交付'],['R4','R4 商业承诺或订单'],['R5','R5 实际收入'],['R6','R6 持续合作']])}${selectField('收入公开授权','visibility',[['private','不公开具体金额'],['range','仅公开区间'],['amount','公开金额']])}${textarea('成果说明与证据摘要','description','','说明客户、交付、验收或到账之间的对应关系。')}<div class="field full"><label for="proof">证明材料（仅记录文件名）</label><input type="file" id="proof" name="proof" multiple></div>${check('我有权提交这些证明，理解核验本身不自动增加积分或奖金。')}</div>`,'提交核验',!!blocked))}`,'participant');}
function organizerPage(){ensureDemoSeasons();const choices=[...new Set([state.season.code,...Object.keys(state.organizerSeasonRecords||{})])];return layout(`${pageHead('赛季工作台',state.season.name+' · '+seasonStatus(),button('预览公开赛季','#season'))}<section class="org-section" aria-labelledby="org-output"><h2 id="org-output">参与和产出</h2><div class="grid cols-4">${stat('已通过选手',state.applications.filter(a=>a.status==='已通过').length,'按本季审核通过人数统计')}${stat('已发布项目',allProjects().length)}${stat('已发布作品',state.works.length)}${stat(['ended','archived','settling'].includes(state.phase)?'评分总次数':'今日有效评分', ['ended','archived','settling'].includes(state.phase)?effective().length:effective().filter(l=>l.date===new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})).length,'时间按北京时间统计')}</div></section><section class="org-section" aria-labelledby="org-budget"><h2 id="org-budget">预算使用情况</h2><div class="grid cols-2">${panel('奖励预算','奖励金额与可评积分分别记录。',`<div class="grid cols-2">${stat('本季奖励池',money(state.season.budget))}${stat('预计过程奖励',money(used()*state.season.ratio),'未核定不代表已到账')}</div><div class="org-inline-actions">${button('预算与结算','#budget','sm')}</div>`)}${panel('可评积分','评委分配额度不是项目已得分。',`<div class="grid cols-3">${stat('积分池总量',state.season.pool)}${stat('已用',used())}${stat('未分配',state.season.pool-allocated())}</div><div class="progress"><span style="width:${state.season.pool?Math.min(100,used()/state.season.pool*100):0}%"></span></div>${button('评委与积分池','#points','sm')}`)}</div></section><section class="org-section" aria-labelledby="org-todos"><h2 id="org-todos">待处理事项</h2><div class="grid cols-4">${panel('报名审核','待审核 '+state.applications.filter(a=>a.status==='审核中').length+' 人',button('审核报名','#applications','sm'))}${panel('里程碑审核','待处理 '+state.milestones.filter(m=>m.status==='待审核').length+' 项',button('查看里程碑','#review','sm'))}${panel('大额评分复核','待复核 '+effective().filter(l=>!l.reviewed).length+' 笔',button('查看评分复核','#review','sm'))}${panel('结算待办',state.phase==='settling'?'正在结算':'查看异议与核定进度',button('查看结算','#budget','sm'))}</div></section>`,'organizer');}
function seasonConfigPage(){const labels=['报名开放','报名截止','开赛','组队截止','命题冻结','作品截止','评分截止','结算日'];const numeric=(label,name,value,min=1,max='')=>field(label,name,'number',value,false,`min="${min}" step="1" ${max?'max="'+max+'"':''}`);return layout(`${pageHead('赛季配置','按本季配置生成规则，发布前完成必备条件。',button('发布检查','#publish-check','primary'))}${form('season-config',`<section class="panel form-section"><h2>基本信息</h2><div class="form-grid">${field('赛季名称','name','text',state.season.name,false,'minlength="2"')}${field('赛季编号','code','text',state.season.code,false,'readonly')}${selectField('赛季类型','seasonType',[['season','常规赛季'],['hackathon','黑客松']],state.season.type||'season')}${selectField('形式标签（仅常规赛季，可选）','formatLabel',[['','无'],...SEASON_FORMAT_LABELS.map(l=>[l,l])],seasonFormatTag()||'')}${field('举办城市（线上赛季填线上）','city','text',state.season.city||'线上')}${field('赛季主题','themeName','text',state.season.themeName||'真实需求与商业验证',true)}${textarea('赛季介绍','theme',state.season.theme)}</div></section><section class="panel form-section"><h2>主办与发奖信息</h2><div class="form-grid">${(()=>{const selected=seasonOrganizerOrgs();const options=[...new Set([...(state.organizations||[]).map(o=>o.name),...selected])];return `<div class="field full"><label class="required">主办方组织（可多选）</label><div class="org-checks">${options.map(name=>`<label class="check"><input type="checkbox" name="organizerOrgs" value="${esc(name)}" ${selected.includes(name)?'checked':''}><span>${esc(name)}</span></label>`).join('')}</div>${state.role==='admin'?button('新增组织','add-organization','sm'):'<span class="help">组织与成员由平台管理员维护，需新增或修改请联系平台管理员。</span>'}</div>`;})()}${field('赛季负责人','owner','text',state.season.owner||'温禾')}${field('发奖主体','payer','text',state.season.payer)}${selectField('核验员配置','reviewer',[['yes','已由平台配置授权核验员'],['no','尚未配置']],state.season.reviewer?'yes':'no')}</div></section><section class="panel form-section"><h2>赛程设置</h2><p class="small muted">所有时间均为北京时间。</p><div class="form-grid">${labels.map((label,i)=>field(label,'date'+i,'date',state.season.dates[i])).join('')}</div></section><section class="panel form-section"><h2>参赛与评分规则</h2><div class="form-grid">${numeric('每个项目命题上限','challengeLimit',state.season.challengeLimit||3,1,3)}${numeric('每人项目数','projectLimit',state.season.projectLimit||1)}${numeric('核心团队人数上限','teamLimit',state.season.teamLimit||3,1,3)}${numeric('单次评分上限','cap',state.season.cap)}${field('每积分对应金额（元）','ratio','number',state.season.ratio,false,`min="0.01" step="0.01" ${state.phase!=='upcoming'?'readonly':''}`)}${numeric('大额复核阈值','threshold',state.season.threshold)}${numeric('本季奖励预算（元）','budget',state.season.budget,0)}<label class="check"><input type="checkbox" name="daily" ${state.season.daily?'checked':''}><span>开启每日可评额度限制（默认关闭）</span></label><label class="check"><input type="checkbox" name="noScoring" ${state.season.scoringEnabled===false?'checked':''}><span>不计分活动（预热季、共学季等形式标签类可选）：不设积分池、评委与预计奖金，免除对应发布门槛；黑客松不可选</span></label></div><p class="help">开赛后兑换比例锁定；评委和积分分配在“评委与积分池”中管理。</p></section><section class="panel form-section"><h2>公开规则卡</h2><p class="small muted">必要条目由配置生成且不能隐藏；可选条目每行一条，可在保存前调整行序或删除。</p>${rules({hideScoring:state.season.scoringEnabled===false})}<div style="margin-top:22px">${textarea('可选规则条目','optionalRules',(state.season.optionalRules||[]).join('\n'),'发布后修改会保留版本并生成公告。').replace(' required','')}</div></section><section class="panel form-section"><h2>发布操作</h2><div class="row">${button('保存为草稿','make-draft','',state.phase!=='upcoming')}${button('查看发布检查','#publish-check')}${seasonPublishButton(true)}</div><p class="help">提交审核前会保存当前配置并检查发布条件，通过平台审核后公开。发起新赛季或复制已有赛季，请前往侧栏的“赛季发起”。</p></section>`,'保存配置')}`,'organizer');}
function seasonPublishButton(saveFirst=false){const approved=state.season.approved&&!state.season.draft;const pending=!state.season.approved&&!state.season.draft;const label=approved?'已发布':pending?'审核中':saveFirst?(state.role==='admin'?'保存并发布':'保存并提交审核'):(state.role==='admin'?'发布赛季':'提交审核');const disabled=approved||pending;return saveFirst?`<button type="submit" name="intent" value="publish" class="btn primary" ${disabled?'disabled':''}>${label}</button>`:button(label,'submit-season','primary',disabled);}
/* SEA-006：不计分活动免除 预算、积分池、评委 三项发布门槛。 */
function publishChecks(){const scoring=state.season.scoringEnabled!==false;return [['赛程完整且先后合法',state.season.dates.every(Boolean)],['至少一个已发布命题',selectableChallenges().length>0],...(scoring?[['奖励预算大于零',state.season.budget>0],['积分池总量大于零',state.season.pool>0],['至少一位评委已获积分分配',state.judges.some(j=>j.active&&j.allocated>0)]]:[['不计分活动：免除预算、积分池与评委门槛',true]]),['至少一位核验员',state.season.reviewer],['规则与协议版本已确定',true],['至少一个主办方组织',seasonOrganizerOrgs().length>0],['发奖主体已确定',!!state.season.payer]];}
function publishCheckPage(){const items=publishChecks();return layout(`${pageHead('公开之前，把承诺准备好。','预算、命题、评委和发奖主体都需要在发布前备齐。')}${panel('必备条件清单','主办方提交后需平台批准才公开和开赛。',`<ul class="checklist">${items.map(([l,ok])=>`<li class="${ok?'':'missing'}"><span class="mark">${ok?'✓':'!'}</span><span>${l}</span></li>`).join('')}</ul>${sectionHead('缺失项处理')}${notice(items.some(i=>!i[1])?'尚未满足：'+items.filter(i=>!i[1]).map(i=>esc(i[0])).join('、'):'所有必备条件已满足，可提交发布。')}${button('返回配置补全','#season-config','sm')}${sectionHead('平台审批进度')}<div class="form-footer">${badge(state.season.approved?'已获平台批准':state.season.draft?'草稿':'待平台批准',state.season.approved?'green':'yellow')}${button('保存为新草稿','make-draft')}${seasonPublishButton()}</div>`)}`,'organizer');}
function seasonManagePage(){return layout(`${pageHead('赛程与状态','管理当前赛季的状态与运行安排。')}<div class="stack">${panel('赛季状态','草稿和待平台批准只对本组织与平台管理员可见。',`<div class="row">${badge(seasonStatus(),'pink')}${badge(state.season.approved?'已获批准':'尚未批准')}</div><p>${esc(SEASON_STATUS_NOTES[seasonStatus()])}</p>${state.season.owner?`<p class="small muted">赛季负责人：${esc(state.season.owner)}</p>`:''}`)}${panel('赛程调整','本人赛季可直接调整，无需平台重新批准；修改须公告留痕。',`${timeline()}<div class="org-inline-actions">${button('修改赛程','#season-config')}</div>`)}${panel('开赛与暂停','已批准才能开赛；暂停时停止报名、作品与评分，不自动顺延截止。',`<div class="row">${button('开赛','start-season','primary',!state.season.approved||state.phase!=='upcoming')}${button(state.phase==='suspended'?'恢复赛季':'暂停赛季',state.phase==='suspended'?'resume-season':'pause-season','',!['active','workClosed','suspended'].includes(state.phase))}${button('进入结算','enter-settling','',!['active','workClosed'].includes(state.phase))}</div>`)}${panel('取消赛季','未开赛可由主办方取消，已开赛须平台管理员执行；积分保留为档案，不发奖。',button('取消赛季','cancel-season','danger',['ended','archived','cancelled'].includes(state.phase)||(state.phase!=='upcoming'&&state.role!=='admin')))}${panel('操作记录','状态和赛程变更留痕。',logsTable())}</div>`,'organizer');}
function applicationsPage(){const rows=state.applications.filter(a=>activeFilter==='全部'||a.status===activeFilter);return layout(`${pageHead('报名与拉群','审核通过后赋予本季资格，微信群由主办方人工邀请。')}${sectionHead('报名审核')}${notice('审核出结果前可执行：通过、待定、候补、拒绝、代本人撤回。拒绝必须填写原因，原因会展示给本人。')}${tabs(['全部','审核中','待定','已通过','候补','未通过','已撤回'],activeFilter)}${listState(table(['申请人','技能与方向','审核状态','微信群','操作'],rows.map(a=>[`<strong>${esc(a.name)}</strong><span class="sub">${esc(a.time)}</span>`,`${esc(a.skills)}<span class="sub">${esc(a.direction)}</span>`,badge(a.status,a.status==='已通过'?'green':'yellow')+(a.reason&&['未通过','已撤回'].includes(a.status)?`<span class="sub">${esc(a.reason)}</span>`:''),badge(a.group||'待邀请'),`<div class="row">${['审核中','待定'].includes(a.status)?button('通过','accept:'+a.id,'sm primary')+' '+(a.status==='审核中'?button('待定','defer:'+a.id,'sm')+' ':'')+button('候补','waitlist:'+a.id,'sm')+' '+button('拒绝','reject:'+a.id,'sm')+' '+button('撤回','withdraw-application:'+a.id,'sm'):a.status==='已通过'?button('记录拉群','group:'+a.id,'sm'):button('查看资料','application:'+a.id,'sm')}</div>`])))}${sectionHead('微信邀请记录')}${table(['选手','微信群状态','操作'],state.applications.filter(a=>a.status==='已通过').map(a=>[esc(a.name),badge(a.group||'待邀请'),button('查看并记录拉群','group:'+a.id,'sm')]))}${sectionHead('选手与组队')}${table(['已通过选手','所属项目'],state.applications.filter(a=>a.status==='已通过').map(a=>[esc(a.name),esc(allProjects().find(p=>p.members.includes(a.name))?.name||'尚未组队')]))}${sectionHead('调整申请')}${table(['申请事项','说明','状态'],state.disputes.filter(d=>/调整|团队|命题/.test(d.title)).map(d=>[esc(d.title),esc(d.description),badge(d.status)]))}${notice('候补时限、成员增删与转让的首发范围仍待确认；这里只展示已提出的调整或异议，不预置不存在的申请。')}`,'organizer');}
function challengeHeading(title,actions=''){return `<div class="page-head"><h1>${esc(title)}</h1><div class="page-actions">${actions}</div></div>`;}
function challengeManagePage(){
 const statuses=['全部','草稿','参考资料','已发布','已关闭','已归档'];const items=organizerChallenges();const visible=items.filter(c=>activeFilter==='全部'||c.status===activeFilter);
 return layout(`${challengeHeading('命题管理',button('新增命题','#challenge-edit?id=new','primary',challengeFrozen()).replace('href="#challenge-edit?id=new"',challengeFrozen()?'aria-disabled="true" tabindex="-1"':'href="#challenge-edit?id=new"'))}<div class="row between challenge-toolbar">${tabs(statuses,activeFilter)}${challengeFrozen()?badge('已冻结'):''}</div>${visible.length?table(['命题','企业','状态','已选 / 名额','版本',''],visible.map(c=>[`<a class="challenge-name" href="#challenge-edit?id=${encodeURIComponent(c.id)}">${esc(c.name)}</a>`,esc(c.company),badge(c.status,c.status==='已发布'?'green':c.status==='草稿'?'yellow':''),`${c.taken} / ${c.capacity}`,`V${c.version}`,button('查看',`#challenge-edit?id=${encodeURIComponent(c.id)}`,'sm')])):empty('暂无命题')}`,state.role==='admin'?'admin':'organizer');
}
function challengeEditPage(){
 const id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');const isNew=id==='new';const c=isNew?{id:'new',name:'',company:'',type:'解决方案 / POC',description:'',resource:'',target:'',evidence:'',verifier:'',reward:'',rights:'',capacity:6,taken:0,status:'草稿',version:1,versions:[]}:managedChallenge();
 if(!c||isNew&&challengeFrozen())return layout(`${button('← 命题管理','#challenge-manage','link')}${empty(isNew?'命题已冻结':'命题不存在')}`,state.role==='admin'?'admin':'organizer');
 const versions=new URLSearchParams(location.hash.split('?')[1]||'').get('tab')==='versions';const locked=['已关闭','已归档'].includes(c.status);const optional=(label,name,value)=>textarea(label,name,value).replace(/ required/g,'').replace('class="required"','');
 const section=(title,body)=>`<section class="panel form-section"><h2>${title}</h2><div class="form-grid">${body}</div></section>`;
 const progressLink=!isNew&&c.status!=='草稿'?button('查看进度','#challenge-progress?id='+encodeURIComponent(c.id),'sm'):'';
 const content=section('问题与资源',`${field('命题名称','name','text',c.name,true)}${field('企业','company','text',c.company)}${selectField('命题类型','type',['商单验证','上下游合作','解决方案 / POC','数据 / 研究'],c.type)}${optional('真实问题','description',c.description)}${optional('资源承诺','resource',c.resource)}`)+section('证据与评分',`${optional('最小成果','target',c.target)}${optional('证据门槛','evidence',c.evidence)}${field('核验人','verifier','text',c.verifier,true).replace(/ required/g,'').replace('class="required"','')}${optional('评分与奖励','reward',c.reward)}`)+section('权益与授权',optional('授权范围与权益条款','rights',c.rights));
 const history=c.versions.length?c.versions.slice().reverse().map(v=>`<details class="challenge-version"><summary>V${v.version} · ${esc(v.date||'')} · ${esc(v.status)}</summary><dl>${[['命题名称','name'],['真实问题','description'],['资源承诺','resource'],['最小成果','target'],['证据门槛','evidence'],['核验人','verifier'],['评分与奖励','reward'],['权益条款','rights'],['名额','capacity']].map(([label,key])=>`<dt>${label}</dt><dd>${esc(v[key]??'—')}</dd>`).join('')}</dl></details>`).join(''):empty('暂无历史版本');
 const sidebar=`<aside class="panel challenge-settings"><div class="row between">${badge(c.status,c.status==='已发布'?'green':'')}${badge('V'+c.version)}</div>${challengeFrozen()?`<div class="challenge-freeze">${badge('已冻结')}</div>`:''}<div class="challenge-capacity">${field('项目名额','capacity','number',c.capacity,false,`min="${Math.max(1,c.taken)}" step="1" ${locked?'disabled':''}`)}<span class="small muted">已选 ${c.taken}</span></div><div class="challenge-actions"><button class="btn" type="submit" value="save" ${locked?'disabled':''}>保存${c.status==='草稿'?'草稿':''}</button>${['草稿','参考资料'].includes(c.status)?`<button class="btn primary" type="submit" value="publish" ${challengeFrozen()?'disabled':''}>发布命题</button>${c.status==='草稿'?`<button class="btn" type="submit" value="reference" ${challengeFrozen()?'disabled':''}>存为参考资料</button>`:''}`:''}${c.status==='已发布'?`<button class="btn danger" type="button" data-action="close-challenge:${esc(c.id)}" ${challengeFrozen()?'disabled':''}>关闭命题</button>`:''}${c.status==='已关闭'?button('归档','archive-challenge:'+c.id):''}</div></aside>`;
 return layout(`<a class="link" href="#challenge-manage">← 命题管理</a>${challengeHeading(isNew?'新增命题':c.name,progressLink)}${!isNew?`<nav class="tabs" aria-label="命题详情"><a class="${versions?'':'active'}" href="#challenge-edit?id=${encodeURIComponent(c.id)}">内容</a><a class="${versions?'active':''}" href="#challenge-edit?id=${encodeURIComponent(c.id)}&tab=versions">版本记录${c.versions.length?' · '+c.versions.length:''}</a></nav>`:''}${versions?`<section class="panel">${history}</section>`:`<form data-form="challenge-edit"><input type="hidden" name="id" value="${esc(c.id)}"><div class="challenge-editor"><div><fieldset ${locked?'disabled':''}>${content}</fieldset><div class="form-error" role="alert"></div></div>${sidebar}</div></form>`}`,state.role==='admin'?'admin':'organizer');
}
function pointsPage(adminMode=false){const role=adminMode?'admin':'organizer';return layout(`${pageHead(adminMode?'全平台积分与评委':'评委与积分池','所有额度来自赛季积分池；收回的只能是尚未使用的部分。',button('追加积分池','add-pool','primary'))}${sectionHead('赛季可评积分')}<div class="grid cols-4">${stat('积分池总量',state.season.pool)}${stat('已分配',allocated())}${stat('已用',used())}${stat('未分配',state.season.pool-allocated())}</div>${sectionHead('评委名单与权限',button('新增评委','add-judge','sm'))}${table(['评委','作用范围','分配 / 已用 / 剩余','状态','操作'],state.judges.map(j=>[`<strong>${esc(j.name)}</strong><span class="sub">${esc(j.company)}</span>`,j.scope==='all'?'本赛季全部项目':esc(organizerChallenges().find(c=>c.id===j.scope)?.company||'本企业'),`${j.allocated} / ${judgeUsed(j.id)} / <strong>${j.allocated-judgeUsed(j.id)}</strong>`,badge(j.active?'有效':'已暂停',j.active?'green':''),`<div class="row">${button('分配','allocate:'+j.id,'sm')}${button('回收','reclaim:'+j.id,'sm')}${button(j.active?'暂停':'恢复','toggle-judge:'+j.id,'sm')}</div>`]))}${sectionHead('评委积分分配')}${notice('通过评委行中的“分配”和“回收”操作调整额度，只能回收未用部分。')}${sectionHead('额度与停用')}${panel('可选的防刷限制','默认关闭；开启后限制每位评委按北京时间自然日可使用的额度。',`<div class="row between"><div>${badge(state.season.daily?'已开启：每日 300 分':'默认关闭',state.season.daily?'green':'')}<p class="small muted" style="margin-top:10px">当日未用额度不转入其他配额池。</p></div>${button(state.season.daily?'关闭每日额度':'开启每日额度','toggle-daily')}</div>`)}` ,role);}
function reviewPage(){const waiting=effective().filter(l=>!l.reviewed);return layout(`${pageHead('审核与复核','里程碑认证、评分复核与商业核验分别处理。')}${sectionHead('里程碑审核')}${table(['项目与阶段','提交说明','状态','操作'],state.milestones.map(m=>[`${esc(projectBy(m.projectId).name)} / M${m.step}`,esc(m.description),badge(m.status,m.status==='已通过'?'green':'yellow'),m.status==='待审核'?button('审核','review-milestone:'+m.id,'sm'):'已处理']))}${sectionHead('大额评分复核')}${table(['作品','原评委','评分','理由','操作'],waiting.map(l=>[esc(workBy(l.workId).title),esc(l.judge),l.points,esc(l.reason),button('处理复核','review-score:'+l.id,'sm')]))}${sectionHead('商业结果核验')}${notice('主办方身份本身不附带核验授权。本原型把核验操作放在平台管理员界面。')}${table(['成果','等级','状态'],state.results.map(r=>[esc(r.title),esc(r.level),badge(r.status)]))}${sectionHead('异议与处理记录')}${disputesTable()}`,'organizer');}
function budgetPage(){return layout(`${pageHead('预算与结算','结算中处理完阻断项，才能核定和定格成绩。',button('追加预算','add-budget'))}<div class="grid cols-3">${stat('本季奖励预算',money(state.season.budget))}${stat('过程贡献预计奖金',money(used()*state.season.ratio))}${stat('已发放',state.rewardsPaid?money(used()*state.season.ratio):'¥0')}</div>${sectionHead('奖励预算')}${table(['资金类别','金额','用途'],[['过程奖励池',money(state.season.budget),'用于选手过程贡献奖励'],['管理费','单独核算','不进入选手奖励账本'],['平台服务费','单独核算','不进入选手奖励账本']])}${sectionHead('结算前检查')}${panel('必须先解决的事项','有待复核评分、超预算或未解决分配争议时，不能定格。',`<ul class="checklist">${[['待复核评分',effective().filter(l=>!l.reviewed).length===0],['预计金额不超预算',used()*state.season.ratio<=state.season.budget],['没有未处理异议',state.disputes.every(d=>['已解决','已驳回'].includes(d.status))]].map(([t,ok])=>`<li class="${ok?'':'missing'}"><span class="mark">${ok?'✓':'!'}</span>${t}${ok?'：已满足':'：待处理'}</li>`).join('')}</ul><div class="row" style="margin-top:22px">${button('进入结算中','enter-settling','',!['active','workClosed'].includes(state.phase))}${button('核定并定格本季','settle','primary',state.phase!=='settling')}${button('记录已发放','pay','',!['ended','archived'].includes(state.phase)||state.rewardsPaid)}</div>`)}${sectionHead('奖金核定')}${rankingTable()}${sectionHead('发放与最终结果')}${notice(state.phase==='cancelled'?'赛季取消，不核定、不发放奖励，积分留档。':state.rewardsPaid?'已记录本季奖励发放，成绩和流水保留。':'定格后奖励转为已核定，再记录发放进度；实际发款需另行执行。')}`,'organizer');}
function announcementsPage(){return layout(`${pageHead('公告','首发通知使用站内公告与未读红点。',button('发布公告','new-notice','primary'))}${sectionHead('公告内容')}${listState(`<div class="stack">${state.announcements.map(n=>panel(n.title,`${n.date} / ${n.target}`,`<p>${esc(n.body)}</p>${badge(n.read?'已读':'未读',n.read?'':'pink')}`)).join('')}</div>`)}${sectionHead('通知对象')}${notice('发布时可选择全体用户、本赛季报名用户或本赛季选手；个人定向事件仍按待定规则处理。')}${sectionHead('未读提醒')}${notice('目标用户收到站内未读红点，打开后标为已读；不发送邮件、短信或微信模板消息。')}`,'organizer');}
function judgeScopeLabel(){const j=judge();if(!j)return '当前没有有效评委授权';return j.scope==='all'?'范围：本赛季全部项目':'范围：仅选择了 '+(organizerChallenges().find(c=>c.id===j.scope)?.company||'本企业')+' 命题的项目';}
function judgePage(){const pending=state.works.filter(w=>checkedScope(w)&&!effective().some(l=>l.workId===w.id&&l.version===w.version&&l.judgeId===actor));return layout(`${pageHead('好的判断，让真实行动被看见。','仅对授权范围内的作品评分，本人参与的项目需要回避。',button('我的评分记录','#my-scores'))}<div class="grid cols-3">${stat('已分配额度',judge()?.allocated||0)}${stat('本季已用',judgeUsed(actor))}${stat('剩余可评积分',(judge()?.allocated||0)-judgeUsed(actor),judgeScopeLabel())}</div>${sectionHead('待评分作品',button('查看评分参考','#score-guide','sm'))}${canWrite('score')?notice(esc(canWrite('score'))):''}${workList(pending,true)}`,'judge');}
function scoreBlock(w){if(w.authorId===actor||state.ownProject?.id===w.projectId)return '这是你参与的项目，需要回避。';if(!checkedScope(w))return '这件作品不在你的授权范围内。';if(effective().some(l=>l.workId===w.id&&l.version===w.version&&l.judgeId===actor))return '你已经评价过这个版本，不能重复评分。';return canWrite('score');}
function scorePage(){const requestedId=new URLSearchParams(location.hash.split('?')[1]||'').get('id');if(!requestedId){const pending=state.works.filter(w=>checkedScope(w)&&!effective().some(l=>l.workId===w.id&&l.version===w.version&&l.judgeId===actor));return layout(`${pageHead('待评分队列','授权范围内、你尚未评分的作品版本；点击作品进入评分。',button('查看评分参考','#score-guide'))}${canWrite('score')?notice(esc(canWrite('score'))):''}${pending.length?workList(pending,true):empty('暂无待评分作品','授权范围内发布新作品或新版本后，会出现在这里。',button('返回评委台','#judge'))}`,'judge');}const w=state.works.find(x=>x.id===requestedId);if(!w)return layout(empty('找不到这件作品','它可能已被移除，请从待评分队列重新选择。',button('返回待评分队列','#score')),'judge');const blocked=scoreBlock(w);return layout(`${pageHead('作品评分','对当前作品版本独立判断，并留下可以解释的理由。')}<div class="review-layout"><div>${panel(w.title,`${projectBy(w.projectId).name} / ${w.author} / V${w.version}`,`<div class="work-body">${w.body.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="evidence">▧ ${esc(w.evidence.join('、'))}</div>`)}<div style="margin-top:22px">${panel('已有评分','其他评委已评过，不影响你独立评价；同一评委对同一版本只评一次。',table(['评委','分数','状态'],state.ledger.filter(l=>l.workId===w.id).map(l=>[esc(l.judge),l.reversed?`<s>${l.points}</s>`:l.points,badge(l.reversed?'已冲正':l.reviewed?'有效':'待复核')])) )}</div></div><div class="sticky-panel">${panel('你的评分','可用额度 '+((judge()?.allocated||0)-judgeUsed(actor))+' / 单次上限 '+state.season.cap,`${blocked?notice(esc(blocked)):''}${form('score',`<input type="hidden" name="workId" value="${w.id}"><div class="form-grid">${field('分值（正整数）','points','number','',true,`min="1" max="${state.season.cap}" step="1"`)}${textarea('评分理由','reason','','至少十二字，说明证据和价值判断。')}</div><details><summary>五维评分参考</summary><p>真实商业结果、交付与客户价值、原创与洞察、行动与迭代、共建与复用。五维用于引导判断，不是强制计算公式。</p></details><p class="help">达到 ${state.season.threshold} 分会进入第二人复核。评分不能超过你的余额或赛季奖励预算。</p>`,'确认评分',!!blocked)}`)}<div class="row" style="margin-top:14px">${button('要求补充','request-evidence:'+w.id,'sm')}${button('不予赋分','no-score:'+w.id,'sm')}${button('提交前检查',`#score-check?id=${w.id}`,'sm')}</div></div></div>`,'judge');}
function guidePage(){return layout(`${pageHead('五个方向，帮助你作出判断。','五维是价值引导，不能把点赞、发文数或收入金额直接换算积分。')}<div class="grid cols-2">${[['01','真实商业结果','是否有真实客户、外部交付、订单或合作？'],['02','交付与客户价值','交付质量如何，是否解决了客户真实的问题？'],['03','原创方法与产业洞察','是否形成有价值的新方法或产业判断？'],['04','行动、证据与有效迭代','是否有行动、可靠证据和可解释的改进？'],['05','共建、开源和复用价值','是否能帮助他人，或在授权范围内复用？']].map(([i,t,d])=>panel(i+' / '+t,'',`<p>${d}</p>`)).join('')}</div>${notice('真实性、合法合规与隐私是一票否决项。企业满意度不能作为唯一评分依据。','pink')}${button('返回待评分队列','#score','primary')}`,'judge');}
function scoreCheckPage(){const w=currentWork();if(!w)return layout(empty('还没有可检查的评分','请先从评委台选择作品。',button('返回评委台','#judge')),'judge');const blocked=scoreBlock(w);return layout(`${pageHead('提交前检查','检查当前版本、授权与可用额度。')}${panel(w.title,'',`<ul class="checklist">${[['评分身份',state.role==='judge'],['赛季进行中且未过评分截止',['active','workClosed'].includes(state.phase)],['评分授权有效',judge()?.active],['作品在授权范围',checkedScope(w)],['不存在重复评分',!effective().some(l=>l.workId===w.id&&l.version===w.version&&l.judgeId===actor)],['不是本人项目',w.authorId!==actor&&state.ownProject?.id!==w.projectId]].map(([t,ok])=>`<li class="${ok?'':'missing'}"><span class="mark">${ok?'✓':'!'}</span>${t}</li>`).join('')}</ul><p style="margin-top:18px">${blocked?esc(blocked):'条件已满足。具体分值仍需通过单次上限、每日额度和预算校验。'}</p>${button('返回评分表单',`#score?id=${w.id}`,'primary')}`)}`,'judge');}
function myScoresPage(){return layout(`${pageHead('我的评分记录','历史评分保留；更正通过管理员冲正，不覆盖原记录。')}${table(['作品','版本','分数','理由','状态'],state.ledger.filter(l=>l.judgeId===actor).map(l=>[`<a href="#work?id=${l.workId}">${esc(workBy(l.workId).title)}</a>`,'V'+l.version,l.reversed?`<s>${l.points}</s>`:l.points,esc(l.reason),badge(l.reversed?'已冲正':l.reviewed?'有效':'待复核')]))}`,'judge');}
function enterprisePage(){
 const items=enterpriseChallenges();const visible=items.filter(c=>activeFilter==='全部'||enterpriseSubmissionStatus(c)===activeFilter);const projects=allProjects().filter(p=>items.some(c=>c.status!=='草稿'&&p.challenges.includes(c.id)));
 return layout(`${challengeHeading('本企业命题',button('创建新命题','#challenge-draft','primary'))}<div class="grid cols-3 enterprise-stats">${stat('已发布',items.filter(c=>c.status==='已发布').length)}${stat('相关项目',projects.length)}${stat('奖金池出资',money(5000))}</div>${tabs(['全部','待发布','参考资料','已发布','已关闭','已归档'],activeFilter)}${visible.length?table(['命题','状态','发布活动','相关项目','版本',''],visible.map(c=>[`<a class="challenge-name" href="#enterprise-challenge?id=${encodeURIComponent(c.id)}">${esc(c.name)}</a>`,badge(enterpriseSubmissionStatus(c),c.status==='已发布'?'green':c.status==='草稿'?'yellow':''),esc(challengePublishedActivity(c)?.name||'—'),projectsForChallenge(c.id).length,'V'+c.version,button('查看','#enterprise-challenge?id='+encodeURIComponent(c.id),'sm')])):empty('暂无命题')}`,'enterprise');
}
function enterpriseDraftsPage(){const items=enterpriseUnsubmittedDrafts();return layout(`${challengeHeading('命题草稿',button('创建新命题','#challenge-draft','primary'))}${items.length?table(['命题',''],items.map(c=>[`<a class="challenge-name" href="#challenge-draft?id=${encodeURIComponent(c.id)}">${esc(c.name||'未命名命题')}</a>`,button('继续编辑','#challenge-draft?id='+encodeURIComponent(c.id),'sm')])):empty('暂无命题草稿')}`,'enterprise');}
function challengeReadContent(c){return `<div class="grid cols-2">${[['问题与资源',[['真实问题',c.description],['资源承诺',c.resource],['最小成果',c.target]]],['证据与权益',[['证据门槛',c.evidence],['核验人',c.verifier],['评分与奖励',c.reward],['权益条款',c.rights]]]].map(([title,fields])=>panel(title,'',`<dl class="challenge-read">${fields.map(([label,value])=>`<dt>${label}</dt><dd>${esc(value||'—')}</dd>`).join('')}</dl>`)).join('')}</div>`;}
function enterpriseChallengePage(){
 const c=enterpriseChallenge();if(!c)return layout(`${button('← 本企业命题','#enterprise','link')}${empty('命题不存在')}`,'enterprise');
 return layout(`${button('← 本企业命题','#enterprise','link')}${challengeHeading(c.name)}<div class="chips enterprise-meta">${badge(enterpriseSubmissionStatus(c),c.status==='已发布'?'green':'')}${badge(c.type)}${badge('V'+c.version)}${challengePublishedActivity(c)?badge(challengePublishedActivity(c).name):''}</div><nav class="tabs"><a class="active" href="#enterprise-challenge?id=${encodeURIComponent(c.id)}">内容</a>${c.status!=='草稿'?`<a href="#report?id=${encodeURIComponent(c.id)}">项目进度</a>`:''}</nav>${challengeReadContent(c)}`,'enterprise');
}
function challengeDraftPage(){
 const id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');const c=id?enterpriseUnsubmittedDrafts().find(item=>item.id===id):{};
 if(!c)return layout(`${button('← 命题草稿','#enterprise-drafts','link')}${empty('草稿不存在或已提交')}`,'enterprise');
 const optional=(label,name,value)=>textarea(label,name,value||'').replace(/ required/g,'').replace('class="required"','');
 return layout(`${button('← 命题草稿','#enterprise-drafts','link')}${challengeHeading(id?'编辑命题草稿':'创建新命题')}<section class="panel"><form data-form="challenge-draft"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="form-grid">${field('命题名称','name','text',c.name||'',true)}${selectField('命题类型','type',['商单验证','上下游合作','解决方案 / POC','数据 / 研究'],c.type||'商单验证')}${field('目标客户','customer','text',c.customer||'').replace(/ required/g,'').replace('class="required"','')}${textarea('真实问题与最小成果','description',c.description||'')}${optional('资源承诺','resources',c.resources)}${optional('完成标准与证据','evidence',c.evidence)}${optional('权益条款','rights',c.rights??'项目保留知识产权，企业使用成果须另行确认授权。')}</div><div class="form-error" role="alert"></div><div class="form-footer"><a class="btn" href="#enterprise-drafts">返回</a><button type="submit" class="btn" value="save-draft" formnovalidate>保存草稿</button><button type="submit" class="btn primary" value="submit">提交主办方</button></div></form></section>`,'enterprise');
}
function resourcesPage(){
 const ids=enterpriseChallenges().filter(c=>c.status!=='草稿').map(c=>c.id);const projects=allProjects().filter(p=>p.challenges.some(id=>ids.includes(id)));
 return layout(`${challengeHeading('资源与交付')}${table(['资源','承诺内容','负责人','状态',''],[['测试算力','200 GPU 小时','Orion AI 技术团队'],['专家支持','两位技术导师','林舟'],['园区试点','3 家试点团队','程远']].map(([a,b,c],i)=>[a,b,c,badge(state.resources[i],state.resources[i]==='已提供'?'green':'yellow'),button('更新状态','resource:'+i,'sm')]))}<section class="panel enterprise-deliveries"><h2>交付</h2>${table(['项目','成果',''],projects.map(p=>[esc(p.name),esc(p.r||'R0'),button('记录验收','accept-delivery:'+p.id,'sm')]))}</section>`,'enterprise');
}
function challengeProgressBody(c){const projects=projectsForChallenge(c.id),works=publicChallengeWorks(c.id);return `<div class="grid cols-3 enterprise-stats">${stat('相关项目',projects.length)}${stat('公开作品',works.length)}${stat('项目积分',projects.reduce((sum,p)=>sum+projectScore(p),0))}</div>${projects.length?table(['项目','团队','阶段','成果','积分',''],projects.map(p=>[`<a class="challenge-name" href="#project?id=${encodeURIComponent(p.id)}">${esc(p.name)}</a>`,esc(p.members.join('、')),esc(p.stage||'—'),esc(p.r||'—'),projectScore(p),button('查看项目','#project?id='+encodeURIComponent(p.id),'sm')])):empty('暂无项目')}<section class="panel enterprise-deliveries"><h2>公开作品</h2>${works.length?workList(works):empty('暂无公开作品')}</section>`;}
function reportPage(){const c=enterpriseChallenge();if(!c||c.status==='草稿')return layout(`${button('← 本企业命题','#enterprise','link')}${empty('暂无项目进度')}`,'enterprise');return layout(`${button('← 本企业命题','#enterprise','link')}${challengeHeading(c.name)}<nav class="tabs"><a href="#enterprise-challenge?id=${encodeURIComponent(c.id)}">内容</a><a class="active" href="#report?id=${encodeURIComponent(c.id)}">项目进度</a></nav>${challengeProgressBody(c)}`,'enterprise');}
function challengeProgressPage(){const c=currentChallenge();if(!canReadChallenge(c))return layout(`<div class="container">${empty('命题尚未公开')}</div>`);return layout(`<div class="container">${button('← 命题详情','#challenge?id='+encodeURIComponent(c.id),'link')}${challengeHeading(c.name)}<nav class="tabs"><a href="#challenge?id=${encodeURIComponent(c.id)}">内容</a><a class="active" href="#challenge-progress?id=${encodeURIComponent(c.id)}">项目进度</a></nav>${challengeProgressBody(c)}</div>`);}
function partnershipPage(){return layout(`${challengeHeading('合作与出资')}<div class="grid cols-2">${panel('奖金池与合作','',`<ul class="rule-list"><li><strong>奖金池出资</strong><span>¥5,000</span></li><li><strong>平台服务费</strong><span>单独核算，不计入选手奖励</span></li><li><strong>资源支持</strong><span>测试算力、技术专家和园区试点</span></li><li><strong>成果使用</strong><span>按项目接受的权益条款，额外许可另行签约</span></li></ul>`)}${panel('推荐评委','',form('recommend',`<div class="form-grid">${field('候选人姓名','name','text','',true)}${textarea('推荐理由与利益关系','reason')}</div>`,'提交推荐'))}</div>`,'enterprise');}

function logsTable(){return table(['时间（北京时间）','操作人身份','操作','说明'],state.logs.slice(0,30).map(l=>[esc(l.date),esc(l.actor),esc(l.action),esc(l.detail)]));}
function disputesTable(){return table(['事项','说明','状态','操作'],state.disputes.map(d=>[esc(d.title),esc(d.description),badge(d.status),['已解决','已驳回'].includes(d.status)?'已处理':button('处理','dispute:'+d.id,'sm')]));}
function adminPage(){return layout(`${pageHead('平台赛季治理','批准公开、唯一置顶与已开赛取消，由平台管理员负责。')}<div class="grid cols-3">${stat('待批准赛季',state.season.approved?0:1)}${stat('全平台置顶',1,'新的置顶会替换旧的置顶')}${stat('待处理异议',state.disputes.filter(d=>d.status==='待处理').length)}</div>${sectionHead('赛季列表')}${table(['赛季','主办方','状态','审批','操作'],[[`<strong>${esc(state.season.name)}</strong><span class="sub">${esc(state.season.code)}</span>`,esc(state.season.organizer),badge(phase()),badge(state.season.approved?'已批准':state.season.draft?'草稿':'待批准',state.season.approved?'green':'yellow'),`<div class="row">${button('预览','#season','sm')}${!state.season.approved?button('批准','approve-season','sm primary')+button('驳回','reject-season','sm'):button('设为唯一置顶','pin-season','sm')}${button('取消','cancel-season','sm danger')}</div>`]])}${sectionHead('最近治理记录')}${logsTable()}`,'admin');}
function organizationsPage(){return layout(`${pageHead('主办方组织与成员','组织只在被指定的赛季内拥有主办方权限。',button('新增组织','add-organization','primary'))}${table(['组织','负责人','成员数','负责赛季','操作'],state.organizations.map((o,i)=>[esc(o.name),esc(o.owner),o.members,esc(state.season.code),`<div class="row">${button('添加成员','add-member:'+i,'sm')}${button('重命名','rename-organization:'+i,'sm')}${button('删除','remove-organization:'+i,'sm danger')}</div>`]))}${notice('多组织在同一赛季同权；成员不能凭主办方身份直接评分或核验收入。')}`,'admin');}
function ledgerPage(){return layout(`${pageHead('评分记录与纠错','不直接改历史分值。冲正会保留原记录，并同步重算积分和预计奖金。')}${table(['记录','作品 / 评委','分值','状态','操作'],state.ledger.map(l=>[esc(l.id),`${esc(workBy(l.workId).title)}<span class="sub">${esc(l.judge)} / V${l.version}</span>`,l.reversed?`<s>+${l.points}</s> / -${l.points}`:'+'+l.points,badge(l.reversed?'已冲正':l.reviewed?'有效':'待复核',l.reversed?'':l.reviewed?'green':'yellow'),l.reversed?'原记录保留':button('冲正','reverse:'+l.id,'sm danger')]))}${sectionHead('审计记录')}${logsTable()}`,'admin');}
function adminResultsPage(){return layout(`${pageHead('结果、预算与争议','核验人检查证据，复核人不能是原评委。')}${sectionHead('商业核验申请')}${table(['成果','项目','等级','状态','操作'],state.results.map(r=>[esc(r.title),esc(projectBy(r.projectId).name),esc(r.level),badge(r.status),r.status==='待核验'?button('核验','verify:'+r.id,'sm'):'已处理']))}${sectionHead('待复核评分')}${table(['作品','评分人','分数','操作'],effective().filter(l=>!l.reviewed).map(l=>[esc(workBy(l.workId).title),esc(l.judge),l.points,button('处理','review-score:'+l.id,'sm')]))}${sectionHead('异议')}${disputesTable()}${sectionHead('预算与结算')}<div class="grid cols-3">${stat('奖励池',money(state.season.budget))}${stat('有效评分',used())}${stat('待复核',effective().filter(l=>!l.reviewed).length)}</div><div class="row" style="margin-top:22px">${button('进入结算','enter-settling','',!['active','workClosed'].includes(state.phase))}${button('核定并定格','settle','primary',state.phase!=='settling')}${button('记录发放','pay','',!['ended','archived'].includes(state.phase)||state.rewardsPaid)}</div>`,'admin');}
function projectsPage(){const projects=state.role==='visitor'?guestProjects():allProjects();return layout(`<div class="container">${pageHead('产品共生','项目长期存在，每个赛季的成绩分别留下。')}<div class="grid cols-3">${projects.map(p=>projectCard(p,{score:false})).join('')}</div></div>`);}
function talentPage(){return layout(`<div class="container">${pageHead('共鸣之地','先认识彼此，再一起把事情做出来。')}${notice('这里只展示公开资料，不公开微信群联系方式。完整招募与匹配不在本次原型范围内。')}<div class="grid cols-3">${[['苏禾','产品设计 / 用户研究','寻找技术搭档'],['林可','品牌运营 / 商业合作','欢迎一起做小额试点'],['周予','研究 / 数据分析','寻找产品验证方向']].map(([n,t,d])=>panel(n,t,`<p>${d}</p>${badge('愿意认识队友','pink')}`)).join('')}</div></div>`);}
function organizerSeasonSelect(){ensureDemoSeasons();return `<select id="organizer-season" class="sidebar-season-select" aria-label="切换管理赛季">${organizerSeasonCodes().map(code=>{const item=code===state.season.code?state:state.organizerSeasonRecords[code];return `<option value="${esc(code)}" ${code===state.season.code?'selected':''}>${esc(item.season.name)} · ${esc(seasonStatus(item))}</option>`;}).join('')}</select>`;}
function organizerSeasonCodes(){return [...new Set([state.season.code,...Object.keys(state.organizerSeasonRecords||{})])];}
function organizerSeasonsPage(){ensureDemoSeasons();return layout(`${pageHead('全部赛季','选择一个赛季进入工作台。')}<div class="season-status-grid">${organizerSeasonCodes().map(code=>{const item=code===state.season.code?state:state.organizerSeasonRecords[code];const status=seasonStatus(item);return `<button type="button" class="season-status-card" data-action="select-season" data-id="${esc(code)}">${badge(status,'pink')}<strong>${esc(item.season.name)}</strong><span>${esc(SEASON_STATUS_NOTES[status])}</span></button>`;}).join('')}</div>`,'organizer');}
function seasonCreatePage(){return layout(`${pageHead('赛季发起','先创建赛季草稿，再完善赛程、规则与预算。')}${panel('发起新赛季','填写基本信息，创建后进入赛季配置。',form('season-create',`<div class="form-grid">${field('赛季名称','name','text','',true,'minlength="2"')}${selectField('赛季类型','seasonType',[['season','常规赛季'],['hackathon','黑客松']],'season')}${field('举办城市（线上赛季填线上）','city','text','线上')}<label class="check"><input type="checkbox" name="noScoring"><span>不计分活动：不设积分池、评委与奖励，页面不显示积分与排行榜（仅常规赛季可选）</span></label></div>`,'创建草稿并配置'))}${panel('从已有赛季复制',`以“${esc(state.season.name)}”为基础，保留基本信息和规则，不复制预算、积分池、评委、命题与报名。`,button('复制为新草稿','copy-season'))}`,'organizer');}
function organizerDraftsPage(){ensureDemoSeasons();const codes=organizerSeasonCodes().filter(code=>seasonStatus(code===state.season.code?state:state.organizerSeasonRecords[code])==='草稿');return layout(`${pageHead('草稿','继续完善尚未提交发布的赛季。',button('发起赛季','#season-create','primary'))}${codes.length?`<div class="season-status-grid">${codes.map(code=>{const item=code===state.season.code?state:state.organizerSeasonRecords[code];return `<button type="button" class="season-status-card" data-action="edit-season-draft" data-id="${esc(code)}">${badge('草稿','pink')}<strong>${esc(item.season.name)}</strong><span>继续配置 →</span></button>`;}).join('')}</div>`:empty('暂无草稿','发起一个新赛季，开始准备赛程与规则。',button('发起赛季','#season-create','primary'))}`,'organizer');}
const PAGES={'season-create':seasonCreatePage,'organizer-drafts':organizerDraftsPage,'organizer-seasons':organizerSeasonsPage,seasons:seasonsPage,home:seasonsPage,season:seasonPage,challenges:challengesPage,challenge:challengePage,archive:archivePage,rankings:rankingsPage,apply:applyPage,'create-project':createProjectPage,project:projectPage,'new-work':newWorkPage,work:workPage,milestone:milestonePage,result:resultPage,organizer:organizerPage,'season-config':seasonConfigPage,'publish-check':publishCheckPage,'season-manage':seasonManagePage,applications:applicationsPage,'challenge-manage':challengeManagePage,'challenge-edit':challengeEditPage,'admin-challenges':challengeManagePage,'enterprise-challenge':enterpriseChallengePage,'enterprise-drafts':enterpriseDraftsPage,'challenge-progress':challengeProgressPage,points:()=>pointsPage(),review:reviewPage,budget:budgetPage,announcements:announcementsPage,judge:judgePage,score:scorePage,'score-guide':guidePage,'score-check':scoreCheckPage,'my-scores':myScoresPage,enterprise:enterprisePage,'challenge-draft':challengeDraftPage,resources:resourcesPage,report:reportPage,partnership:partnershipPage,admin:adminPage,organizations:organizationsPage,'admin-points':()=>pointsPage(true),ledger:ledgerPage,'admin-results':adminResultsPage,projects:projectsPage,talent:talentPage};

function seasonDetailAction(route,label,kind='primary'){return button(label,'enter-public-activity:'+state.season.code+':'+route,kind);}
function seasonPersonalApplication(){return ['participant','visitor'].includes(state.role)?state.application:null;}
/* CHG-006：赛季主题是独立展示维度，不替代项目命题；配置了 themeName 时作为标签公开展示。 */
function seasonPosterBadges(){return `<div class="chips season-state-badges">${badge(activityDisplayStatus(),'pink')}${registrationDisplayLabel()?badge(registrationDisplayLabel()):''}${seasonFormatTag()?badge(seasonFormatTag()):''}${state.season.themeName?badge('主题 · '+state.season.themeName):''}${badge(seasonOrganizerLabel())}${badge(state.season.city||'线上')}</div>`;}
function seasonPosterDate(label,start,end){return `<div class="season-state-dates season-poster-date"><span class="season-poster-date-label"><img src="assets/season-details/calendar.svg" alt=""><span>${esc(label)}</span></span><span class="season-poster-date-range">${esc(start||'待公布')} — ${esc(end||'待公布')}</span></div>`;}
function seasonFollowButton(){return button(state.role!=='visitor'&&state.followed?'已关注赛季':'关注赛季','follow-public-activity:'+state.season.code,'season-hero-follow');}
function seasonApplicationPanel(){const application=seasonPersonalApplication();if(!application)return '';const passed=application.status==='已通过';return `<section class="panel season-personal-panel"><div><h2>${['ended','archived'].includes(state.phase)?'我的赛季记录':'报名审核'}</h2><div class="chips">${badge(application.status,passed?'green':application.status==='候补'?'yellow':'')}${state.ownProject?badge(state.ownProject.name):''}</div></div><div class="row">${seasonDetailAction(passed&&state.ownProject?'project':'workspace',passed?(state.ownProject?'进入项目':'进入我的赛季'):application.status==='候补'?'查看候补状态':'查看报名状态')}${passed&&state.ownProject&&state.phase==='active'?seasonDetailAction('new-work','发布赛季作品','')+seasonDetailAction('milestone','查看下一里程碑',''):''}</div></section>`;}
function seasonTimelineSegmentProgress(start,next,now=Date.now()){const from=new Date(start+'T00:00:00+08:00').getTime(),to=next?new Date(next+'T00:00:00+08:00').getTime():from;if(!Number.isFinite(from))return 0;if(to<=from||!Number.isFinite(to))return now>=from?100:0;return Math.max(0,Math.min(100,(now-from)/(to-from)*100));}
// Demo data uses hardcoded phases, so the timeline derives a fixed "now" from the
// activity's own phase/registration instead of the real clock — the two can never disagree.
function seasonTimelineNow(record=state){
 const t=d=>d?new Date(d+'T00:00:00+08:00').getTime():NaN;
 const mid=(a,b)=>Number.isFinite(a)?(Number.isFinite(b)?(a+b)/2:a):NaN;
 const dates=record.season.dates||[],day=86400000;
 const phase=['cancelled','suspended'].includes(record.phase)&&record.previousPhase?record.previousPhase:record.phase;
 if(['ended','archived'].includes(phase))return t(dates[7])+day;
 if(phase==='upcoming')return record.registration==='open'?mid(t(dates[0]),t(dates[1])):record.registration==='closed'?mid(t(dates[1]),t(dates[2])):t(dates[0])-day;
 if(phase==='workClosed')return mid(t(dates[5]),t(dates[6]));
 if(phase==='settling')return mid(t(dates[6]),t(dates[7]));
 return mid(Math.max(t(dates[2]),t(dates[3]),t(dates[4])),t(dates[5]));
}
function seasonDetailTimeline(){
 const labels=['报名开放','报名截止','开赛','组队截止','命题冻结','作品截止','评分截止','结算'];const nodes=labels.map((label,index)=>({label,index,date:state.season.dates[index]})).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.index-b.index);
 const now=seasonTimelineNow(),finished=['ended','archived'].includes(state.phase);const reached=nodes.filter(node=>finished||new Date(node.date+'T00:00:00+08:00').getTime()<=now).map(node=>node.index);const current=finished?-1:nodes.filter(node=>reached.includes(node.index)).at(-1)?.index??-1;
 return `<div class="season-timeline-block"><div class="timeline season-detail-timeline" data-stage="${esc(activityDisplayStatus())}">${nodes.map((node,index)=>{const done=reached.includes(node.index);const isCurrent=current===node.index&&!['ended','archived','cancelled'].includes(state.phase);const progress=['ended','archived'].includes(state.phase)?100:seasonTimelineSegmentProgress(node.date,nodes[index+1]?.date,now);return `<div style="--segment-progress:${progress.toFixed(2)}%" class="timeline-item ${done?'done':''} ${isCurrent?'current':''}" ${isCurrent?'aria-current="step"':''}><strong>${node.label}</strong><span>${esc(node.date||'待公布')}</span></div>`;}).join('')}</div><p class="small muted season-timeline-timezone">截止时间均为北京时间 23:59</p></div>`;
}
